type TimeSinceUnit = 'year' | 'month' | 'day' | 'hour' | 'minute' | 'second'

interface TimeSinceResult {
  value: number
  unit: TimeSinceUnit
}

export function timeSince(date: number): TimeSinceResult {
  const seconds = Math.floor((Date.now() - date) / 1000)

  let interval = seconds / 31536000
  if (interval > 1) {
    return { value: Math.floor(interval), unit: 'year' }
  }

  interval = seconds / 2592000
  if (interval > 1) {
    return { value: Math.floor(interval), unit: 'month' }
  }

  interval = seconds / 86400
  if (interval > 1) {
    return { value: Math.floor(interval), unit: 'day' }
  }

  interval = seconds / 3600
  if (interval > 1) {
    return { value: Math.floor(interval), unit: 'hour' }
  }

  interval = seconds / 60
  if (interval > 1) {
    return { value: Math.floor(interval), unit: 'minute' }
  }

  return { value: Math.floor(seconds), unit: 'second' }
}

export function convertDurationToText(duration: number) {
  return `${`00${Math.floor(duration / 60)}`.slice(-2)}:${`00${(duration % 60)}`.slice(-2)}`
}

export function convertMillisecondsToDate(milliseconds: number) {
  const date = new Date(milliseconds)
  return `${date.getFullYear()}-${`00${date.getMonth() + 1}`.slice(-2)}-${`00${date.getDate()}`.slice(-2)}`
}
