<script setup lang="ts">
import { IonContent, IonPage, useIonRouter } from '@ionic/vue'
import { onMounted, ref } from 'vue'
import { userService } from '@/services/user'

import type { NotificationResModel } from '@/types/notification'
import HeaderWithReturn from '@/components/HeaderWithReturn.vue'
import MyAvatar from '@/components/MyAvatar.vue'
import CommonButton from '@/components/CommonButton.vue'
import { convertMillisecondsToDate } from '@/utils/timeSince'
import IconWithBackround from '@/components/IconWithBackround.vue'
import NotificationCenterSekaiItem from '@/components/items/NotificationCenterSekaiItem.vue'

const ionRouter = useIonRouter()
const notifications = ref<NotificationResModel[]>([])

onMounted(() => {
  fetchNotifications()
})

async function fetchNotifications() {
  // fetch notifications
  try {
    const res = await userService.fetchNotifications()
    notifications.value = res.data
  }
  catch (error) {
    console.error(error)
  }
}

async function followOperation(userId: number, isFollow: boolean) {
  try {
    await userService.followOperations(
      userId,
      isFollow ? 'follow' : 'unfollow',
    )
  }
  catch (error) {
    console.error(error)
  }
}
</script>

<template>
  <ion-page>
    <header-with-return title="Notifications" />
    <ion-content>
      <div
        v-for="n in notifications"
        :key="n.id"
        class="flex items-center gap-3 px-4 py-3"
      >
        <div
          v-if="n.entityType === 0 && 'userId' in n.entityInfo"
          class="flex items-center gap-3"
          @click="
            () => {
              if ('userId' in n.entityInfo) {
                ionRouter.push(`/profile?userId=${n.entityInfo.userId}`);
              }
            }
          "
        >
          <my-avatar
            :src="n.entityInfo.avatarUrl"
            :user-name="n.entityInfo.userName"
          />
          <div class="flex flex-col">
            <p class="text-2.75 fw-400 color-#7A7A7A">
              {{ convertMillisecondsToDate(n.created * 1000) }}
            </p>
            <p class="text-3.5 color-#fff fw-600 leading-normal">
              {{ n.entityInfo.userName }} has followed you
            </p>
            <p class="text-3 fw-400 color-#B8B8B8">
              Click the Follow button to follow back
            </p>
          </div>
          <common-button
            text="Follow Back"
            bg-color="bg-#00F4FF"
            text-color="text-on-primary"
            @click="
              () => {
                if ('userId' in n.entityInfo) {
                  followOperation(n.entityInfo.userId, true);
                }
              }
            "
          />
        </div>
        <div
          v-else-if="n.entityType === 1 && 'universeId' in n.entityInfo"
          class="flex items-center gap-3"
          @click="
            () => {
              if ('universeId' in n.entityInfo) {
                ionRouter.push(`/sekai/${n.entityInfo.universeId}`);
              }
            }
          "
        >
          <icon-with-backround v-if="n.actionType === 2" type="like" />
          <icon-with-backround v-if="n.actionType === 3" type="interact" />
          <icon-with-backround v-if="n.actionType === 4" type="publish" />
          <div class="flex flex-col">
            <p class="text-2.75 fw-400 color-#7A7A7A">
              {{ convertMillisecondsToDate(n.created * 1000) }}
            </p>
            <p class="text-3.5 color-#fff fw-600 leading-normal">
              {{ n.message }}
            </p>
            <div class="w-">
              <notification-center-sekai-item
                :sekai="n.entityInfo"
              />
            </div>
          </div>
        </div>
      </div>
    </ion-content>
  </ion-page>
</template>
